{
  "icon": "IconSettings",
  "title": "数据中心",
  "isOpen": true,
  "items": [
    {
      "id": "page_gonghui_data_001",
      "name": "公会数据",
      "component": {
        "cardArea": {
          "gap": "16px",
          "show": false,
          "columns": 4,
          "cards": [
            {
              "key": "totalGuilds",
              "title": "总公会数",
              "value": ""
            },
            {
              "key": "newGuilds",
              "title": "新增公会数",
              "value": ""
            },
            {
              "key": "guildFlow",
              "title": "公会流水",
              "value": ""
            }
          ]
        },
        "tableArea": {
          "height": "500px",
          "fixedLayout": true,
          "pageSize": 10,
          "columns": [
            {
              "key": "guildId",
              "label": "公会ID",
              "width": "100px",
              "visible": true,
              "mockFormat": "number"
            },
            {
              "key": "guildName",
              "label": "公会名称",
              "width": "120px",
              "visible": true,
              "mockFormat": "text"
            },
            {
              "key": "guildCountry",
              "label": "公会国家",
              "width": "150px",
              "visible": true,
              "mockFormat": "text"
            },
            {
              "key": "guildType",
              "label": "公会类型",
              "width": "100px",
              "visible": true,
              "type": "select",
              "mockFormat": "list",
              "mockList": ["类型A", "类型B", "类型C"]
            },
            {
              "key": "guildLevel",
              "label": "公会等级",
              "width": "100px",
              "visible": true,
              "type": "select",
              "mockFormat": "list",
              "mockList": ["1级", "2级", "3级", "4级", "5级"]
            },
            {
              "key": "targetProgress",
              "label": "目标完成进度",
              "width": "120px",
              "visible": true,
              "mockFormat": "number"
            }
          ]
        },
        "filterArea": {
          "gap": "16px",
          "columns": 4,
          "filters": [
            {
              "key": "guildId",
              "type": "input",
              "label": "公会ID",
              "placeholder": "请输入公会ID",
              "visible": true
            },
            {
              "key": "guildName",
              "type": "input",
              "label": "公会名称",
              "placeholder": "请输入公会名称",
              "visible": true
            },
            {
              "key": "guildLeaderId",
              "type": "input",
              "label": "公会会长ID",
              "placeholder": "请输入会长ID",
              "visible": true
            },
            {
              "key": "guildLevelFilter",
              "type": "select",
              "label": "公会等级",
              "options": ["全部", "1级", "2级", "3级", "4级", "5级"],
              "placeholder": "请选择等级",
              "visible": true
            },
            {
              "key": "guildTypeFilter",
              "type": "select",
              "label": "公会类型",
              "options": ["全部", "类型A", "类型B", "类型C"],
              "placeholder": "请选择类型",
              "visible": true
            },
            {
              "key": "acmFilter",
              "type": "select",
              "label": "ACM",
              "options": ["全部", "是", "否"],
              "placeholder": "请选择ACM",
              "visible": true
            },
            {
              "key": "timeFilter",
              "type": "date-range",
              "label": "时间",
              "placeholder": "请选择时间范围",
              "visible": true
            }
          ]
        },
        "actionsArea": {
          "show": true,
          "buttons": [
            {
              "key": "search",
              "label": "搜索",
              "variant": "outline",
              "visible": true
            },
            {
              "key": "exportSummary",
              "label": "导出汇总数据",
              "variant": "primary",
              "visible": true
            },
            {
              "key": "exportDetail",
              "label": "导出明细数据",
              "variant": "outline",
              "visible": true
            }
          ]
        }
      }
    }
  ]
}
